class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    @classmethod
    def from_string(cls, s):
        name, age = s.split(',')
        return cls(name, int(age))

person = Person.from_string('Alice,30')
print(person.name)

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    @staticmethod
    def is_adult(age):
        return age >= 18

print(Person.is_adult(20))
print(Person.is_adult(15))

class Person:
    def __init__(self, first_name, last_name):
        self.first_name = first_name
        self.last_name = last_name

    @property
    def full_name(self):
        return f'{self.first_name} {self.last_name}'

person = Person('Ada', 'Lovelace')
print(person.full_name)

class Thermometer:
    def __init__(self, temperature_c):
        self.temperature_c = temperature_c

    @property
    def temperature_c(self):
        return self._temp

    @temperature_c.setter
    def temperature_c(self, value):
        if value < -273.15:
            raise ValueError('Below absolute zero!')
        self._temp = value

t = Thermometer(21.5)
print(t.temperature_c)
t.temperature_c = 30
print(t.temperature_c)

try:
    t.temperature_c = -500
except ValueError as e:
    print(e)

class Person:
    count = 0

    def __init__(self, name):
        self.name = name
        Person.count += 1

    @classmethod
    def get_count(cls):
        return cls.count

Person('Alice')
Person('Bob')
Person('Carol')
print(Person.get_count())

